<script setup lang="ts">
import { iconGroup } from './theme'
import { computed, onMounted, ref, watch } from 'vue'
import { typeIcons, typeLabels, type QualityReport } from '../../schemas/src/index'
import { api, canEdit, currentProject, dateLabel, projectDocuments, state } from './state'
defineEmits<{ search: [] }>()
const quality = ref<QualityReport | null>(null); const loading = ref(false); const error = ref('')
const recent = computed(() => [...projectDocuments.value].sort((a,b) => b.metadata.updated_at.localeCompare(a.metadata.updated_at)).slice(0,6))
const metrics = computed(() => [
  { title:'Tài liệu đã xuất bản', value:projectDocuments.value.length, href:'/library/', kind:'reference', icon:'mdi-book-open-page-variant-outline' },
  { title:'Quy trình nghiệp vụ', value:projectDocuments.value.filter(d=>d.metadata.type==='business-flow').length, href:'/business-flows/', kind:'business-flow', icon:'mdi-transit-connection-variant' },
  { title:'Quy tắc nghiệp vụ', value:projectDocuments.value.filter(d=>d.metadata.type==='business-rule').length, href:'/business-rules/', kind:'business-rule', icon:'mdi-scale-balance' },
  { title:'Màn hình nghiệp vụ', value:projectDocuments.value.filter(d=>d.metadata.type==='screen').length, href:'/screens/', kind:'screen', icon:'mdi-monitor' }
])
let sequence = 0
async function load() { const request = ++sequence; quality.value = null; if (!canEdit.value || !state.project) return; loading.value=true;error.value=''; try { const result = await api<QualityReport>(`/api/quality?project_id=${encodeURIComponent(state.project)}`); if(request===sequence) quality.value=result } catch(failure) {if(request===sequence)error.value=(failure as Error).message} finally {if(request===sequence)loading.value=false} }
onMounted(load); watch(() => state.project, load)
</script>
<template>
  <header class="workspace-heading"><div><span class="eyebrow">Không gian làm việc <span v-if="currentProject?.demo" class="demo-pill">Dữ liệu minh họa</span></span><h1>{{ currentProject?.name || 'Tri thức của đội ngũ' }}</h1><p>{{ currentProject?.description || 'Tìm thông tin nghiệp vụ, kiểm tra nguồn và cùng cập nhật kiến thức.' }}</p></div><v-btn v-if="canEdit && state.project" color="primary" prepend-icon="mdi-plus" href="/studio/?new=reference">Tạo tài liệu</v-btn></header>
  <button class="dashboard-search" @click="$emit('search')"><v-icon icon="mdi-magnify" size="26" /><span><strong>Bạn đang cần hiểu điều gì?</strong><small>Tìm theo tên, ID hoặc nội dung · hỗ trợ tiếng Việt không dấu</small></span><kbd>Ctrl K</kbd></button>
  <div class="metric-grid workspace-metrics"><a v-for="metric in metrics" :key="metric.title" :href="metric.href" class="metric-card"><div class="metric-top"><v-icon :icon="metric.icon" size="22" :class="['semantic-icon',`semantic-${iconGroup(metric.kind)}`]" /><v-icon icon="mdi-arrow-top-right" size="18" /></div><strong>{{ metric.value }}</strong><span>{{ metric.title }}</span></a></div>
  <div class="dashboard-columns"><section class="panel recent-panel"><div class="section-heading"><h2>Gần cập nhật</h2><a href="/library/" class="text-link">Xem thư viện <v-icon icon="mdi-arrow-right" size="18" /></a></div><a v-for="doc in recent" :key="doc.metadata.doc_id" :href="doc.url" class="recent-row document-row"><span class="document-icon"><v-icon :icon="typeIcons[doc.metadata.type]" :class="['semantic-icon',`semantic-${iconGroup(doc.metadata.type)}`]" size="22" /></span><div><strong>{{ doc.metadata.title }}</strong><small>{{ doc.metadata.doc_id }} · {{ typeLabels[doc.metadata.type] }}</small></div><time>{{ dateLabel(doc.metadata.updated_at) }}</time><v-icon icon="mdi-chevron-right" size="18" /></a><div v-if="!recent.length" class="empty-state"><v-icon icon="mdi-book-open-page-variant-outline" size="38" /><h2>Không gian đang chờ tri thức đầu tiên</h2><p>{{ canEdit ? 'Tạo hoặc import tài liệu, hoàn thiện nội dung rồi xuất bản cho đội ngũ.' : 'Tài liệu đã xuất bản của project sẽ xuất hiện tại đây.' }}</p><v-btn v-if="canEdit" href="/studio/" color="primary" variant="tonal">Bắt đầu biên tập</v-btn></div></section>
    <aside class="workspace-aside"><section v-if="canEdit" class="panel"><div class="section-heading"><h2>Cần chú ý</h2><v-icon icon="mdi-check-decagram-outline" color="primary" /></div><v-progress-linear v-if="loading" indeterminate color="primary" /><v-alert v-if="error" type="warning" variant="tonal">{{ error }}<v-btn variant="text" @click="load">Thử lại</v-btn></v-alert><a href="/studio/reviews/" class="attention-row"><span>Đang chờ duyệt</span><strong>{{ quality?.drafts.filter(d=>d.review.status==='in_review').length ?? '—' }}</strong></a><a href="/studio/" class="attention-row"><span>Cần chỉnh sửa</span><strong>{{ quality?.drafts.filter(d=>d.review.status==='changes_requested').length ?? '—' }}</strong></a><a href="/health/" class="attention-row"><span>Quá hạn rà soát</span><strong>{{ quality?.overdue.length ?? '—' }}</strong></a></section>
      <section class="panel"><div class="section-heading"><h2>Điểm bắt đầu</h2></div><a href="/business-flows/" class="quick-link"><span class="icon-box"><v-icon icon="mdi-transit-connection-variant" /></span><span><strong>Hiểu quy trình</strong><small>Tác nhân, điều kiện và ngoại lệ</small></span><v-icon icon="mdi-arrow-right" size="18" /></a><a href="/screens/" class="quick-link"><span class="icon-box"><v-icon icon="mdi-monitor" /></span><span><strong>Tra cứu màn hình</strong><small>Thao tác và hành vi hệ thống</small></span><v-icon icon="mdi-arrow-right" size="18" /></a></section>
    </aside></div>
</template>
